-- DATOS FICTICIOS PARA PRACTICA DE LAS 25 TABLAS.
-- Ejecutar COMPLETO con F5 como KARELY_BD2 en ORCLPDB, despues de la instalacion.
-- Solo agrega datos. No recrea tablas, no desactiva triggers y no envia correos.
-- Una segunda ejecucion detecta la marca de carga y no duplica registros.
-- Los registros historicos se preparan directamente como fixtures; no acreditan
-- que se haya recorrido cada procedimiento transaccional de la aplicacion.
SET DEFINE OFF
SET SERVEROUTPUT ON SIZE UNLIMITED
WHENEVER SQLERROR EXIT SQL.SQLCODE ROLLBACK

DECLARE
    c_marca CONSTANT VARCHAR2(100):='CARGA_PRACTICA_BD_20261124';
    c_hash CONSTANT VARCHAR2(255):='$2a$10$F73MH.M57EzqweWrk7KiCOzvB4z5HTXl7esrODcS5LxjttIftHEvO';
    TYPE numeros IS TABLE OF NUMBER INDEX BY PLS_INTEGER;
    v_doctores numeros;
    v_usuarios_doc numeros;
    v_especialidades numeros;
    v_pacientes numeros;
    v_consultorios numeros;
    v_franjas numeros;
    v_cerradas numeros;
    v_admin NUMBER;
    v_recepcion NUMBER;
    v_tesoreria NUMBER;
    v_bloqueado NUMBER;
    v_clinico NUMBER;
    v_asistencia NUMBER;
    v_activar NUMBER;
    v_receta_parcial NUMBER;
    v_vencida NUMBER;
    v_reprogramada NUMBER;
    v_pre NUMBER;
    v_id NUMBER;
    v_n NUMBER;
    v_precio NUMBER;
    v_saldo NUMBER;
    v_inicio DATE;
    v_fin DATE;
    v_inicio_clinico DATE;
    v_fin_clinico DATE;
    v_franja_recepcion NUMBER;
    v_franja_clinica NUMBER;
    v_anterior VARCHAR2(256):=SYS_CONTEXT('USERENV','CLIENT_IDENTIFIER');

    PROCEDURE contexto_anterior IS
    BEGIN
        IF v_anterior IS NULL THEN DBMS_SESSION.CLEAR_IDENTIFIER;
        ELSE DBMS_SESSION.SET_IDENTIFIER(v_anterior); END IF;
    END;

    PROCEDURE usuario(p_nombre VARCHAR2,p_rol VARCHAR2,p_estado VARCHAR2,p_id OUT NUMBER) IS
        v_rol NUMBER;
    BEGIN
        SELECT ID_ROL INTO v_rol FROM ROL WHERE NOMBRE=p_rol AND ESTADO='ACTIVO';
        INSERT INTO USUARIO(ID_ROL,USERNAME,CORREO,PASSWORD_HASH,ESTADO,INTENTOS_FALLIDOS)
        VALUES(v_rol,p_nombre,p_nombre||'@example.com',c_hash,p_estado,
               CASE WHEN p_estado='BLOQUEADO' THEN 5 ELSE 0 END)
        RETURNING ID_USUARIO INTO p_id;
    END;

    FUNCTION pdf_ficticio RETURN BLOB IS
        v_pdf BLOB;
        -- Documento autocontenido de practica. El bloque hexadecimal se agrega
        -- al generar el archivo distribuible mediante preparar_datos_practica.py.
        v_raw RAW(2000):=HEXTORAW('');
    BEGIN
        DBMS_LOB.CREATETEMPORARY(v_pdf,TRUE);
        DBMS_LOB.WRITEAPPEND(v_pdf,UTL_RAW.LENGTH(v_raw),v_raw);
        RETURN v_pdf;
    END;

    PROCEDURE documento(p_doc NUMBER,p_tipo VARCHAR2,p_estado VARCHAR2) IS
        v_pdf BLOB;
    BEGIN
        v_pdf:=pdf_ficticio;
        INSERT INTO DOCUMENTO_DOCTOR(
            ID_DOCTOR,TIPO_DOCUMENTO,NOMBRE_ARCHIVO,TIPO_MIME,ARCHIVO,HASH,
            ESTADO,FECHA_VALIDACION,USUARIO_VALIDACION)
        VALUES(p_doc,p_tipo,LOWER(p_tipo)||'_'||p_doc||'.pdf','application/pdf',v_pdf,
               NULL,p_estado,
               CASE WHEN p_estado IN ('VALIDADO','RECHAZADO') THEN SYSTIMESTAMP END,
               CASE WHEN p_estado IN ('VALIDADO','RECHAZADO') THEN v_admin END);
        DBMS_LOB.FREETEMPORARY(v_pdf);
    END;

    PROCEDURE especialidad(p_nombre VARCHAR2,p_precio NUMBER,p_estado VARCHAR2,p_id OUT NUMBER) IS
    BEGIN
        SELECT ID_ESPECIALIDAD INTO p_id FROM ESPECIALIDAD
        WHERE NOMBRE=p_nombre;
    EXCEPTION WHEN NO_DATA_FOUND THEN
        INSERT INTO ESPECIALIDAD(NOMBRE,PRECIO_CONSULTA,ESTADO)
        VALUES(p_nombre,p_precio,p_estado) RETURNING ID_ESPECIALIDAD INTO p_id;
    END;

    PROCEDURE franja(p_inicio VARCHAR2,p_fin VARCHAR2,p_id OUT NUMBER) IS
        v_estado FRANJA_HORARIA.ESTADO%TYPE;
    BEGIN
        SELECT ID_FRANJA,ESTADO INTO p_id,v_estado FROM FRANJA_HORARIA
        WHERE HORA_INICIO=p_inicio AND HORA_FIN=p_fin;
        IF v_estado<>'ACTIVO' THEN
            RAISE_APPLICATION_ERROR(-20891,'La franja necesaria existe inactiva: '||p_inicio);
        END IF;
    EXCEPTION WHEN NO_DATA_FOUND THEN
        INSERT INTO FRANJA_HORARIA(HORA_INICIO,HORA_FIN,ESTADO)
        VALUES(p_inicio,p_fin,'ACTIVO') RETURNING ID_FRANJA INTO p_id;
    END;

    PROCEDURE doctor(p_i NUMBER,p_username VARCHAR2,p_nombres VARCHAR2,p_apellidos VARCHAR2,
                     p_documentacion VARCHAR2,p_estado VARCHAR2) IS
        v_correo VARCHAR2(150);
    BEGIN
        usuario(p_username,'DOCTOR','ACTIVO',v_usuarios_doc(p_i));
        v_correo:=p_username||'@example.com';
        INSERT INTO DOCTOR(ID_USUARIO,TIPO_DOCUMENTO,NUMERO_DOCUMENTO,NOMBRES,APELLIDOS,
                           TELEFONO,CORREO,ESTADO_DOCUMENTACION,ESTADO)
        VALUES(v_usuarios_doc(p_i),'DNI',TO_CHAR(74861000+p_i),p_nombres,p_apellidos,
               TO_CHAR(930610000+p_i),v_correo,'INCOMPLETO',p_estado)
        RETURNING ID_DOCTOR INTO v_doctores(p_i);
        documento(v_doctores(p_i),'DNI','VALIDADO');
        IF p_documentacion='COMPLETO' THEN
            documento(v_doctores(p_i),'TITULO','VALIDADO');
        ELSIF p_documentacion='RECHAZADO' THEN
            documento(v_doctores(p_i),'TITULO','RECHAZADO');
        ELSE
            documento(v_doctores(p_i),'TITULO','PENDIENTE');
        END IF;
        UPDATE DOCTOR SET ESTADO_DOCUMENTACION=p_documentacion
        WHERE ID_DOCTOR=v_doctores(p_i);
        INSERT INTO DOCTOR_ESPECIALIDAD(ID_DOCTOR,ID_ESPECIALIDAD)
        VALUES(v_doctores(p_i),v_especialidades(MOD(p_i-1,6)+1));
    END;

    PROCEDURE disponibilidad(p_i NUMBER,p_fecha DATE,p_franja NUMBER) IS
    BEGIN
        INSERT INTO DISPONIBILIDAD_DOCTOR(ID_DOCTOR,ID_FRANJA,FECHA_TURNO,ESTADO,ID_ESPECIALIDAD)
        SELECT v_doctores(p_i),p_franja,TRUNC(p_fecha),'ACTIVO',v_especialidades(p_i)
        FROM DUAL WHERE NOT EXISTS(
            SELECT 1 FROM DISPONIBILIDAD_DOCTOR
            WHERE ID_DOCTOR=v_doctores(p_i) AND ID_FRANJA=p_franja
              AND FECHA_TURNO=TRUNC(p_fecha));
    END;

    PROCEDURE reserva(p_i NUMBER,p_paciente NUMBER,p_cons NUMBER,p_franja NUMBER,
                      p_fecha DATE,p_estado VARCHAR2,p_id OUT NUMBER) IS
        v_bloqueo TIMESTAMP;
    BEGIN
        SELECT PRECIO_CONSULTA INTO v_precio FROM ESPECIALIDAD
        WHERE ID_ESPECIALIDAD=v_especialidades(p_i);
        v_bloqueo:=CASE WHEN p_estado='EXPIRADA'
                       THEN CAST(SYSTIMESTAMP AS TIMESTAMP)-INTERVAL '1' HOUR
                       WHEN p_fecha<TRUNC(SYSDATE)
                       THEN CAST(TRUNC(p_fecha)-7 AS TIMESTAMP)+INTERVAL '8' HOUR
                       ELSE CAST(SYSTIMESTAMP AS TIMESTAMP)-INTERVAL '2' MINUTE END;
        INSERT INTO PRE_RESERVA_CITA(
            ID_PACIENTE,ID_DOCTOR,ID_ESPECIALIDAD,ID_CONSULTORIO,ID_FRANJA,
            FECHA_CITA,MONTO,FECHA_BLOQUEO,FECHA_EXPIRACION,ESTADO)
        VALUES(p_paciente,v_doctores(p_i),v_especialidades(p_i),p_cons,p_franja,
               TRUNC(p_fecha),v_precio,v_bloqueo,v_bloqueo+INTERVAL '10' MINUTE,p_estado)
        RETURNING ID_PRE_RESERVA INTO p_id;
    END;

    PROCEDURE cita(p_i NUMBER,p_paciente NUMBER,p_cons NUMBER,p_franja NUMBER,
                   p_fecha DATE,p_estado VARCHAR2,p_ref VARCHAR2,p_reprog NUMBER,
                   p_id OUT NUMBER) IS
        v_reserva NUMBER;
        v_pago NUMBER;
        v_hora VARCHAR2(5);
        v_turno TIMESTAMP;
        v_atencion NUMBER;
        v_receta NUMBER;
        v_devengo NUMBER;
        v_pdf BLOB;
        v_fecha_pago TIMESTAMP;
    BEGIN
        reserva(p_i,p_paciente,p_cons,p_franja,
                CASE WHEN p_reprog=1 THEN p_fecha+3 ELSE p_fecha END,'CONFIRMADA',v_reserva);
        SELECT FECHA_BLOQUEO+INTERVAL '1' MINUTE INTO v_fecha_pago
        FROM PRE_RESERVA_CITA WHERE ID_PRE_RESERVA=v_reserva;
        INSERT INTO PAGO_CITA(ID_PRE_RESERVA,ID_PACIENTE,MONTO,METODO_PAGO,REFERENCIA_PAGO,FECHA_PAGO,ESTADO)
        VALUES(v_reserva,p_paciente,v_precio,
               CASE WHEN MOD(p_i,2)=0 THEN 'TRANSFERENCIA' ELSE 'EFECTIVO' END,p_ref,v_fecha_pago,'APROBADO')
        RETURNING ID_PAGO INTO v_pago;
        IF p_estado='ATENDIDA' THEN v_devengo:=FN_MONTO_DOCTOR(v_precio); END IF;
        INSERT INTO CITA(ID_PRE_RESERVA,ID_PACIENTE,ID_DOCTOR,ID_ESPECIALIDAD,
                         ID_CONSULTORIO,ID_FRANJA,ID_PAGO,FECHA_CITA,MONTO_TOTAL,
                         MONTO_DOCTOR_DEVENGADO,MONTO_GESTORA_DEVENGADO,ESTADO,REPROGRAMACIONES)
        VALUES(v_reserva,p_paciente,v_doctores(p_i),v_especialidades(p_i),
               p_cons,p_franja,v_pago,TRUNC(p_fecha),v_precio,
               v_devengo,CASE WHEN v_devengo IS NOT NULL THEN v_precio-v_devengo END,
               p_estado,p_reprog)
        RETURNING ID_CITA INTO p_id;
        disponibilidad(p_i,p_fecha,p_franja);
        IF p_reprog=1 THEN
            INSERT INTO REPROGRAMACION_CITA(
                ID_CITA,FECHA_ORIGINAL,ID_FRANJA_ORIGINAL,ID_CONSULTORIO_ORIGINAL,
                FECHA_NUEVA,ID_FRANJA_NUEVA,ID_CONSULTORIO_NUEVO,MOTIVO,
                ACEPTACION_PACIENTE,ID_USUARIO_ACEPTACION)
            VALUES(p_id,TRUNC(p_fecha)+3,p_franja,p_cons,TRUNC(p_fecha),p_franja,p_cons,
                   'Cambio de fecha aceptado por el paciente','S',v_admin);
        END IF;
        SELECT HORA_INICIO INTO v_hora FROM FRANJA_HORARIA WHERE ID_FRANJA=p_franja;
        v_turno:=CAST(TRUNC(p_fecha) AS TIMESTAMP)
                 +NUMTODSINTERVAL(TO_NUMBER(SUBSTR(v_hora,1,2))*60+TO_NUMBER(SUBSTR(v_hora,4,2)),'MINUTE');
        IF p_estado='ATENDIDA' THEN
            INSERT INTO ASISTENCIA(ID_CITA,FECHA_REGISTRO,ESTADO)
            VALUES(p_id,v_turno-INTERVAL '15' MINUTE,'PRESENTE');
            INSERT INTO ATENCION_MEDICA(ID_CITA,ID_DOCTOR,DIAGNOSTICO,OBSERVACIONES,
                                       FECHA_INICIO,FECHA_CIERRE,ESTADO)
            VALUES(p_id,v_doctores(p_i),'Control clinico registrado',
                   'Historia ficticia para practica de base de datos.',
                   v_turno,v_turno+INTERVAL '45' MINUTE,'CERRADA')
            RETURNING ID_ATENCION INTO v_atencion;
            INSERT INTO RECETA(ID_ATENCION,FECHA_EMISION,INDICACIONES)
            VALUES(v_atencion,v_turno+INTERVAL '20' MINUTE,
                   'Indicaciones ficticias; no corresponden a un tratamiento real.')
            RETURNING ID_RECETA INTO v_receta;
            INSERT INTO RECETA_DETALLE(ID_RECETA,MEDICAMENTO,DOSIS,FRECUENCIA,DURACION,OBSERVACIONES)
            VALUES(v_receta,'Paracetamol','500 mg','Cada 8 horas','3 dias','Registro ficticio de practica');
            INSERT INTO RECETA_DETALLE(ID_RECETA,MEDICAMENTO,DOSIS,FRECUENCIA,DURACION,OBSERVACIONES)
            VALUES(v_receta,'Vitamina C','500 mg','Una vez al dia','5 dias','Registro ficticio de practica');
            v_pdf:=pdf_ficticio;
            INSERT INTO RECIBO_HONORARIO(
                ID_CITA,NUMERO_RECIBO,MONTO,FECHA_EMISION,ID_DOCTOR_EMISOR,
                FECHA_ENTREGA,MEDIO_ENTREGA,ID_USUARIO_ENTREGA,ARCHIVO_PDF,CORREO_ENVIO)
            VALUES(p_id,'RH-'||TO_CHAR(p_fecha,'YYYY')||'-'||LPAD(p_id,6,'0'),
                   v_precio,v_turno+INTERVAL '30' MINUTE,v_doctores(p_i),
                   v_turno+INTERVAL '35' MINUTE,'IMPRESO',v_admin,v_pdf,NULL);
            DBMS_LOB.FREETEMPORARY(v_pdf);
            v_cerradas(p_i):=p_id;
        END IF;
    END;

    PROCEDURE atencion_abierta(p_i NUMBER,p_cons NUMBER,p_ref VARCHAR2,
                              p_iniciar CHAR,p_con_receta CHAR,p_id OUT NUMBER) IS
        v_atencion NUMBER;
        v_receta NUMBER;
    BEGIN
        cita(p_i,v_pacientes(p_i),p_cons,v_franja_clinica,TRUNC(SYSDATE),
             'EN_ATENCION',p_ref,0,p_id);
        INSERT INTO ASISTENCIA(ID_CITA,FECHA_REGISTRO,ESTADO)
        VALUES(p_id,CAST(v_inicio_clinico AS TIMESTAMP)-INTERVAL '10' MINUTE,'PRESENTE');
        IF p_iniciar='S' THEN
            INSERT INTO ATENCION_MEDICA(ID_CITA,ID_DOCTOR,FECHA_INICIO,ESTADO,DIAGNOSTICO)
            VALUES(p_id,v_doctores(p_i),CAST(v_inicio_clinico AS TIMESTAMP),'ABIERTA',
                   CASE WHEN p_con_receta='S' THEN 'Evaluacion clinica ficticia registrada' END)
            RETURNING ID_ATENCION INTO v_atencion;
            IF p_con_receta='S' THEN
                INSERT INTO RECETA(ID_ATENCION,INDICACIONES)
                VALUES(v_atencion,'Indicaciones ficticias para completar el ejercicio')
                RETURNING ID_RECETA INTO v_receta;
                INSERT INTO RECETA_DETALLE(ID_RECETA,MEDICAMENTO,DOSIS,FRECUENCIA,DURACION)
                VALUES(v_receta,'Paracetamol','500 mg','Cada 8 horas','3 dias');
            END IF;
        END IF;
    END;

    PROCEDURE liquidar(p_i NUMBER,p_fraccion NUMBER,p_metodo VARCHAR2) IS
        v_monto NUMBER;
        v_num NUMBER;
        v_id_liq NUMBER;
    BEGIN
        v_saldo:=FN_SALDO_DOCTOR(v_doctores(p_i),TRUNC(SYSDATE));
        v_monto:=ROUND(v_saldo*p_fraccion,2);
        IF v_monto<=0 OR v_monto>v_saldo THEN
            RAISE_APPLICATION_ERROR(-20892,'Importe de liquidacion de practica invalido.');
        END IF;
        SELECT SQ_LIQUIDACION_REFERENCIA.NEXTVAL INTO v_num FROM DUAL;
        INSERT INTO LIQUIDACION(ID_DOCTOR,ID_USUARIO_REGISTRO,PERIODO_INICIO,PERIODO_FIN,
                                MONTO,METODO_PAGO,NUMERO_OPERACION,NUMERO_BOLETA,OBSERVACIONES)
        VALUES(v_doctores(p_i),v_tesoreria,TRUNC(SYSDATE)-30,TRUNC(SYSDATE),
               v_monto,p_metodo,'OP-'||TO_CHAR(SYSDATE,'YYYY')||'-'||LPAD(v_num,6,'0'),
               'BOL-'||TO_CHAR(SYSDATE,'YYYY')||'-'||LPAD(v_num,6,'0'),
               'Liquidacion ficticia para practica SQL')
        RETURNING ID_LIQUIDACION INTO v_id_liq;
        INSERT INTO NOTIFICACION_SALIENTE(
            TIPO,DESTINATARIO,ID_LIQUIDACION,ID_USUARIO_CREACION,CODIGO_EVENTO,
            ESTADO,INTENTOS,ULTIMO_ERROR)
        VALUES('PAGO_DOCTOR',NULL,v_id_liq,v_admin,'PRACTICA-LIQ-'||v_id_liq,
               'FALLIDA',5,'Simulacion sin envio de correo');
    END;

BEGIN
    IF USER<>'KARELY_BD2' OR SYS_CONTEXT('USERENV','CON_NAME')<>'ORCLPDB' THEN
        RAISE_APPLICATION_ERROR(-20890,'Ejecutar como KARELY_BD2 en ORCLPDB.');
    END IF;
    SELECT COUNT(*) INTO v_n FROM PARAMETRO_SISTEMA WHERE NOMBRE=c_marca;
    IF v_n>0 THEN
        DBMS_OUTPUT.PUT_LINE('La data de practica ya fue cargada. No se insertaron duplicados.');
        RETURN;
    END IF;
    SELECT COUNT(*) INTO v_n FROM USER_OBJECTS WHERE STATUS='INVALID';
    IF v_n>0 THEN RAISE_APPLICATION_ERROR(-20890,'Revisar objetos invalidos antes de cargar datos.'); END IF;
    SELECT COUNT(*) INTO v_n FROM DOCTOR WHERE NUMERO_DOCUMENTO BETWEEN '74861001' AND '74861009';
    IF v_n>0 THEN RAISE_APPLICATION_ERROR(-20890,'Ya hay doctores en el rango de esta carga. No se modificaron.'); END IF;
    SELECT COUNT(*) INTO v_n FROM PACIENTE WHERE TIPO_DOCUMENTO='DNI'
      AND NUMERO_DOCUMENTO BETWEEN '75861001' AND '75861018';
    IF v_n>0 THEN RAISE_APPLICATION_ERROR(-20890,'Ya hay pacientes en el rango de esta carga. No se modificaron.'); END IF;
    SELECT U.ID_USUARIO INTO v_admin FROM USUARIO U JOIN ROL R ON R.ID_ROL=U.ID_ROL
    WHERE U.USERNAME='admin01' AND U.ESTADO='ACTIVO' AND R.NOMBRE='ADMINISTRADORA';
    SAVEPOINT inicio_practica;
    DBMS_SESSION.SET_IDENTIFIER(TO_CHAR(v_admin));
    INSERT INTO PARAMETRO_SISTEMA(NOMBRE,VALOR,DESCRIPCION,ESTADO)
    VALUES(c_marca,'1','Marca de carga de datos ficticios para practica SQL','ACTIVO');

    usuario('recepcion.norte','RECEPCIONISTA','ACTIVO',v_recepcion);
    usuario('tesoreria.norte','TESORERA','ACTIVO',v_tesoreria);
    usuario('administracion.reserva','ADMINISTRADORA','BLOQUEADO',v_bloqueado);

    especialidad('Medicina General',100,'ACTIVO',v_especialidades(1));
    especialidad('Dermatologia',150,'ACTIVO',v_especialidades(2));
    especialidad('Pediatria',120,'ACTIVO',v_especialidades(3));
    especialidad('Psicologia',110,'ACTIVO',v_especialidades(4));
    especialidad('Medicina Interna',140,'ACTIVO',v_especialidades(5));
    especialidad('Traumatologia',170,'ACTIVO',v_especialidades(6));
    especialidad('Reumatologia',160,'INACTIVO',v_id);
    doctor(1,'dr.alejandro.munoz','Alejandro','Munoz Herrera','COMPLETO','ACTIVO');
    doctor(2,'dra.patricia.rios','Patricia','Rios Salcedo','COMPLETO','ACTIVO');
    doctor(3,'dr.fernando.cabrera','Fernando','Cabrera Ponce','COMPLETO','ACTIVO');
    doctor(4,'dra.camila.ortega','Camila','Ortega Suarez','COMPLETO','ACTIVO');
    doctor(5,'dr.ricardo.aguilar','Ricardo','Aguilar Flores','COMPLETO','ACTIVO');
    doctor(6,'dra.gabriela.morales','Gabriela','Morales Rivera','COMPLETO','ACTIVO');
    doctor(7,'dr.antonio.vidal','Antonio','Vidal Ramos','INCOMPLETO','ACTIVO');
    doctor(8,'dra.veronica.solis','Veronica','Solis Medina','RECHAZADO','ACTIVO');
    doctor(9,'dr.esteban.paz','Esteban','Paz Calderon','COMPLETO','INACTIVO');
    -- Doctor con dos especialidades: permite demostrar GROUP BY y HAVING.
    INSERT INTO DOCTOR_ESPECIALIDAD(ID_DOCTOR,ID_ESPECIALIDAD)
    VALUES(v_doctores(1),v_especialidades(5));

    FOR i IN 1..4 LOOP
        INSERT INTO CONSULTORIO(NOMBRE,UBICACION,ESTADO)
        VALUES('Consultorio Norte '||i,'Sede norte, ambiente '||i,'ACTIVO')
        RETURNING ID_CONSULTORIO INTO v_consultorios(i);
    END LOOP;
    FOR i IN 1..6 LOOP
        franja(LPAD(i+7,2,'0')||':00',LPAD(i+8,2,'0')||':00',v_franjas(i));
    END LOOP;
    FOR i IN 1..18 LOOP
        INSERT INTO PACIENTE(TIPO_DOCUMENTO,NUMERO_DOCUMENTO,NOMBRES,APELLIDOS,
                             FECHA_NACIMIENTO,TELEFONO,CORREO,DIRECCION,ESTADO)
        VALUES('DNI',TO_CHAR(75861000+i),
            CASE i WHEN 1 THEN 'Natalia' WHEN 2 THEN 'Luis Alberto' WHEN 3 THEN 'Daniela'
              WHEN 4 THEN 'Jorge' WHEN 5 THEN 'Rosa Elena' WHEN 6 THEN 'Santiago'
              WHEN 7 THEN 'Adriana' WHEN 8 THEN 'Hugo' WHEN 9 THEN 'Claudia'
              WHEN 10 THEN 'Martin' WHEN 11 THEN 'Valentina' WHEN 12 THEN 'Diego'
              WHEN 13 THEN 'Isabel' WHEN 14 THEN 'Alonso' WHEN 15 THEN 'Luciana'
              WHEN 16 THEN 'Oscar' WHEN 17 THEN 'Teresa' ELSE 'Emilio' END,
            CASE MOD(i-1,6) WHEN 0 THEN 'Castillo Vargas' WHEN 1 THEN 'Benavides Ruiz'
              WHEN 2 THEN 'Mendoza Leon' WHEN 3 THEN 'Salazar Paredes'
              WHEN 4 THEN 'Torres Espinoza' ELSE 'Vega Campos' END,
            ADD_MONTHS(TRUNC(SYSDATE),-12*(18+i)),TO_CHAR(940610000+i),
            'persona.'||i||'.norte@example.com','Av. Los Alamos '||TO_CHAR(100+i),
            CASE WHEN i>=17 THEN 'INACTIVO' ELSE 'ACTIVO' END)
        RETURNING ID_PACIENTE INTO v_pacientes(i);
    END LOOP;

    -- 18 atenciones cerradas completas y 18 citas futuras.
    -- Diferentes horas por doctor evitan cruces dentro de los consultorios nuevos.
    FOR i IN 1..6 LOOP
        FOR dia IN 1..3 LOOP
            cita(i,v_pacientes(i),v_consultorios(MOD(i-1,3)+1),v_franjas(i),
                 TRUNC(SYSDATE)-30+dia*4,'ATENDIDA',
                 'PRACTICA-AT-'||i||'-'||dia,0,v_id);
            cita(i,v_pacientes(i+6),v_consultorios(MOD(i-1,3)+1),v_franjas(i),
                 TRUNC(SYSDATE)+7+dia,'PROGRAMADA',
                 'PRACTICA-FUT-'||i||'-'||dia,0,v_id);
        END LOOP;
    END LOOP;

    -- Reprogramaciones y estados historicos.
    cita(1,v_pacientes(7),v_consultorios(1),v_franjas(1),TRUNC(SYSDATE)+14,
         'REPROGRAMADA','PRACTICA-REPROGRAMADA',1,v_reprogramada);
    cita(2,v_pacientes(8),v_consultorios(2),v_franjas(2),TRUNC(SYSDATE)-10,
         'CANCELADA','PRACTICA-CANCELADA',0,v_id);
    cita(3,v_pacientes(9),v_consultorios(3),v_franjas(3),TRUNC(SYSDATE)-11,
         'CANCELADA','PRACTICA-CANCELADA-REPROG',1,v_id);
    -- PERDIDA se conserva solo como estado historico admitido por el CHECK.
    cita(4,v_pacientes(10),v_consultorios(1),v_franjas(4),TRUNC(SYSDATE)-12,
         'PERDIDA','PRACTICA-PERDIDA-LEGADO',0,v_id);
    cita(5,v_pacientes(11),v_consultorios(2),v_franjas(5),TRUNC(SYSDATE)-1,
         'PROGRAMADA','PRACTICA-VENCIDA',0,v_vencida);

    -- Reserva vigente, reserva expirada y un pago rechazado sin cita confirmada.
    disponibilidad(1,TRUNC(SYSDATE)+21,v_franjas(1));
    reserva(1,v_pacientes(13),v_consultorios(4),v_franjas(1),
            TRUNC(SYSDATE)+21,'BLOQUEADA',v_pre);
    disponibilidad(2,TRUNC(SYSDATE)+22,v_franjas(2));
    reserva(2,v_pacientes(14),v_consultorios(4),v_franjas(2),
            TRUNC(SYSDATE)+22,'EXPIRADA',v_pre);
    INSERT INTO PAGO_CITA(ID_PRE_RESERVA,ID_PACIENTE,MONTO,METODO_PAGO,REFERENCIA_PAGO,ESTADO)
    VALUES(v_pre,v_pacientes(14),v_precio,'TRANSFERENCIA','PRACTICA-PAGO-RECHAZADO','RECHAZADO');

    -- Cita para registrar asistencia ahora, incluso si se cruza la medianoche.
    v_inicio:=TRUNC(SYSDATE,'MI')+10/1440;
    IF TO_CHAR(v_inicio,'HH24:MI')>='23:50' THEN
        v_inicio:=TRUNC(v_inicio)+1+5/1440;
    END IF;
    v_fin:=LEAST(v_inicio+30/1440,TRUNC(v_inicio)+1439/1440);
    franja(TO_CHAR(v_inicio,'HH24:MI'),TO_CHAR(v_fin,'HH24:MI'),v_franja_recepcion);
    cita(1,v_pacientes(13),v_consultorios(4),v_franja_recepcion,TRUNC(v_inicio),
         'PROGRAMADA','PRACTICA-INGRESO-AHORA',0,v_asistencia);

    -- Atenciones en la fecha actual: sin iniciar, abierta vacia y receta parcial.
    v_inicio_clinico:=GREATEST(TRUNC(SYSDATE),TRUNC(SYSDATE,'MI')-5/1440);
    v_fin_clinico:=LEAST(v_inicio_clinico+30/1440,TRUNC(SYSDATE)+1439/1440);
    franja(TO_CHAR(v_inicio_clinico,'HH24:MI'),TO_CHAR(v_fin_clinico,'HH24:MI'),v_franja_clinica);
    atencion_abierta(2,v_consultorios(1),'PRACTICA-CLINICA-ABIERTA','S','N',v_clinico);
    atencion_abierta(3,v_consultorios(2),'PRACTICA-RECETA-PARCIAL','S','S',v_receta_parcial);
    atencion_abierta(4,v_consultorios(3),'PRACTICA-CLINICA-INICIO','N','N',v_activar);

    -- Pagos parciales, pago total y doctores con deuda pendiente.
    liquidar(1,0.50,'EFECTIVO');
    liquidar(2,1,'TRANSFERENCIA');
    liquidar(4,0.25,'TRANSFERENCIA');
    liquidar(6,0.75,'EFECTIVO');

    -- Estados de la cola, todos sin destinatario: no se enviara correo.
    INSERT INTO NOTIFICACION_SALIENTE(
        TIPO,DESTINATARIO,ID_CITA,ID_USUARIO_CREACION,CODIGO_EVENTO,ESTADO,INTENTOS,
        FECHA_ENVIO,ULTIMO_ERROR)
    VALUES('RECIBO_HONORARIO',NULL,v_cerradas(1),v_admin,'PRACTICA-RECIBO-ENVIADO',
           'ENVIADA',1,SYSTIMESTAMP,'Estado simulado; no existio envio externo');
    INSERT INTO NOTIFICACION_SALIENTE(
        TIPO,DESTINATARIO,ID_CITA,ID_USUARIO_CREACION,CODIGO_EVENTO,ESTADO,INTENTOS)
    VALUES('PAGO_CITA',NULL,v_asistencia,v_admin,'PRACTICA-PAGO-PENDIENTE','PENDIENTE',0);

    INSERT INTO SESION_USUARIO(ID_USUARIO,FECHA_INICIO,ULTIMA_ACTIVIDAD,IP_ORIGEN,ESTADO)
    VALUES(v_recepcion,SYSTIMESTAMP,SYSTIMESTAMP,'192.0.2.10','ACTIVA');
    INSERT INTO SESION_USUARIO(ID_USUARIO,FECHA_INICIO,FECHA_FIN,ULTIMA_ACTIVIDAD,IP_ORIGEN,ESTADO)
    VALUES(v_usuarios_doc(1),SYSTIMESTAMP-INTERVAL '2' DAY,SYSTIMESTAMP-INTERVAL '1' DAY,
           SYSTIMESTAMP-INTERVAL '1' DAY,'192.0.2.11','CERRADA');
    INSERT INTO SESION_USUARIO(ID_USUARIO,FECHA_INICIO,FECHA_FIN,ULTIMA_ACTIVIDAD,IP_ORIGEN,ESTADO)
    VALUES(v_bloqueado,SYSTIMESTAMP-INTERVAL '4' HOUR,SYSTIMESTAMP-INTERVAL '3' HOUR,
           SYSTIMESTAMP-INTERVAL '4' HOUR,'192.0.2.12','EXPIRADA');

    -- Tokens ficticios ya vencidos; ninguno habilita una recuperacion vigente.
    INSERT INTO TOKEN_RECUPERACION(
        TOKEN_HASH,ID_USUARIO,CORREO,VERSION_CREDENCIAL,FECHA_CREACION,FECHA_EXPIRACION,FECHA_USO)
    SELECT LOWER(RAWTOHEX(STANDARD_HASH('PRACTICA-TOKEN-EXPIRADO','SHA256'))),
           v_recepcion,'recepcion.norte@example.com',
           LOWER(RAWTOHEX(STANDARD_HASH(c_hash,'SHA256'))),
           SYSTIMESTAMP-INTERVAL '2' DAY,SYSTIMESTAMP-INTERVAL '1' DAY,NULL FROM DUAL;
    INSERT INTO TOKEN_RECUPERACION(
        TOKEN_HASH,ID_USUARIO,CORREO,VERSION_CREDENCIAL,FECHA_CREACION,FECHA_EXPIRACION,FECHA_USO)
    SELECT LOWER(RAWTOHEX(STANDARD_HASH('PRACTICA-TOKEN-USADO','SHA256'))),
           v_usuarios_doc(1),'dr.alejandro.munoz@example.com',
           LOWER(RAWTOHEX(STANDARD_HASH(c_hash,'SHA256'))),
           SYSTIMESTAMP-INTERVAL '3' HOUR,SYSTIMESTAMP-INTERVAL '1' HOUR,
           SYSTIMESTAMP-INTERVAL '2' HOUR FROM DUAL;

    INSERT INTO AUDITORIA(ID_USUARIO,TABLA_AFECTADA,ACCION,DETALLE,ORIGEN)
    VALUES(v_admin,'SISTEMA','CARGA_PRACTICA',
           'Datos ficticios de doctores, pacientes, agenda, atencion, finanzas y seguridad.','SISTEMA');

    -- Verificar que las 25 tablas del modelo tengan registros antes del COMMIT.
    FOR t IN (SELECT TABLE_NAME FROM USER_TABLES
              WHERE TABLE_NAME IN ('ROL','USUARIO','SESION_USUARIO','AUDITORIA','DOCTOR','DOCUMENTO_DOCTOR','ESPECIALIDAD','DOCTOR_ESPECIALIDAD','PACIENTE','CONSULTORIO','FRANJA_HORARIA','DISPONIBILIDAD_DOCTOR','PRE_RESERVA_CITA','PAGO_CITA','CITA','REPROGRAMACION_CITA','ASISTENCIA','ATENCION_MEDICA','RECETA','RECETA_DETALLE','RECIBO_HONORARIO','LIQUIDACION','PARAMETRO_SISTEMA','NOTIFICACION_SALIENTE','TOKEN_RECUPERACION') ORDER BY TABLE_NAME) LOOP
        EXECUTE IMMEDIATE 'SELECT COUNT(*) FROM '||DBMS_ASSERT.SIMPLE_SQL_NAME(t.TABLE_NAME) INTO v_n;
        IF v_n=0 THEN RAISE_APPLICATION_ERROR(-20893,'Tabla sin datos: '||t.TABLE_NAME); END IF;
    END LOOP;
    COMMIT;
    contexto_anterior;
    DBMS_OUTPUT.PUT_LINE('CARGA COMPLETA. Datos ficticios guardados sin eliminar registros anteriores.');
    DBMS_OUTPUT.PUT_LINE('ASISTENCIA AHORA: cita '||v_asistencia||' / turno '||TO_CHAR(v_inicio,'DD/MM/YYYY HH24:MI'));
    DBMS_OUTPUT.PUT_LINE('INICIAR ATENCION: cita '||v_activar);
    DBMS_OUTPUT.PUT_LINE('REGISTRAR DIAGNOSTICO Y RECETA: cita '||v_clinico);
    DBMS_OUTPUT.PUT_LINE('COMPLETAR RECIBO Y CIERRE: cita '||v_receta_parcial);
    DBMS_OUTPUT.PUT_LINE('CITA VENCIDA PARA MANTENIMIENTO: '||v_vencida);
    DBMS_OUTPUT.PUT_LINE('CITA REPROGRAMADA: '||v_reprogramada);
    DBMS_OUTPUT.PUT_LINE('Actor administrativo para procedimientos: '||v_admin);
EXCEPTION WHEN OTHERS THEN
    ROLLBACK;
    contexto_anterior;
    RAISE;
END;
/

