PROMPT ===== DOCTORES DE PRACTICA Y ESTADOS =====
SELECT D.ID_DOCTOR,U.ID_USUARIO,U.USERNAME,D.NOMBRES,D.APELLIDOS,
       D.ESTADO_DOCUMENTACION,D.ESTADO
FROM DOCTOR D JOIN USUARIO U ON U.ID_USUARIO=D.ID_USUARIO
WHERE D.NUMERO_DOCUMENTO BETWEEN '74861001' AND '74861009'
ORDER BY D.NUMERO_DOCUMENTO;

PROMPT ===== CITAS Y CASOS DISPONIBLES =====
SELECT C.ID_CITA,PC.REFERENCIA_PAGO,P.NOMBRES||' '||P.APELLIDOS PACIENTE,
       D.NOMBRES||' '||D.APELLIDOS DOCTOR,C.FECHA_CITA,F.HORA_INICIO,
       C.ESTADO,C.MONTO_TOTAL
FROM CITA C JOIN PAGO_CITA PC ON PC.ID_PAGO=C.ID_PAGO
JOIN PACIENTE P ON P.ID_PACIENTE=C.ID_PACIENTE
JOIN DOCTOR D ON D.ID_DOCTOR=C.ID_DOCTOR
JOIN FRANJA_HORARIA F ON F.ID_FRANJA=C.ID_FRANJA
WHERE PC.REFERENCIA_PAGO LIKE 'PRACTICA-%'
ORDER BY C.FECHA_CITA,F.HORA_INICIO,C.ID_CITA;

PROMPT ===== SALDOS PARA PROBAR LIQUIDACIONES =====
SELECT D.ID_DOCTOR,D.NOMBRES,D.APELLIDOS,
       FN_SALDO_DOCTOR(D.ID_DOCTOR,TRUNC(SYSDATE)) SALDO_PENDIENTE
FROM DOCTOR D WHERE D.NUMERO_DOCUMENTO BETWEEN '74861001' AND '74861006'
ORDER BY D.NUMERO_DOCUMENTO;

PROMPT ===== PACIENTES SIN CITAS PARA LEFT JOIN =====
SELECT P.ID_PACIENTE,P.NUMERO_DOCUMENTO,P.NOMBRES,P.ESTADO
FROM PACIENTE P LEFT JOIN CITA C ON C.ID_PACIENTE=P.ID_PACIENTE
WHERE P.NUMERO_DOCUMENTO BETWEEN '75861001' AND '75861018' AND C.ID_CITA IS NULL;

